starter:
#include <climits>

int halve(int x) {
    return x >> 1;
}

int eighth(int x) {
    return x >> 3;
}

unsigned halve_unsigned(unsigned x) {
    return x >> 1;
}

bool is_odd(int x) {
    return (x & 1) == 1;
}

tests:
CHECK_EQ(halve(10), 5);
CHECK_EQ(halve(11), 5);
CHECK_EQ(halve(0), 0);
CHECK_EQ(halve(-10), -5);
CHECK_EQ(halve(-11), -5);      // C++ rounds towards zero, not towards -infinity
CHECK_EQ(halve(-1), 0);

CHECK_EQ(eighth(64), 8);
CHECK_EQ(eighth(63), 7);
CHECK_EQ(eighth(-64), -8);
CHECK_EQ(eighth(-63), -7);
CHECK_EQ(eighth(-1), 0);

CHECK_EQ(halve_unsigned(10u), 5u);
CHECK_EQ(halve_unsigned(11u), 5u);
CHECK_EQ(halve_unsigned(0u), 0u);
CHECK_EQ(halve_unsigned(4294967294u), 2147483647u);

CHECK(is_odd(3));
CHECK(is_odd(-3));
CHECK(!is_odd(4));
CHECK(!is_odd(-4));
CHECK(!is_odd(0));

// The edge every "just shift it" refactor forgets.
CHECK_EQ(halve(INT_MIN), INT_MIN / 2);
CHECK_EQ(halve(INT_MAX), INT_MAX / 2);

solution:
#include <climits>

int halve(int x) {
    return x / 2;
}

int eighth(int x) {
    return x / 8;
}

unsigned halve_unsigned(unsigned x) {
    return x >> 1;
}

bool is_odd(int x) {
    return (x & 1) != 0;
}
